    "transitions": [
      {
        "condition": "reset",
        "action": "Set count, head and tail to 0; status is 16#0000. Do not clear buffer or write item."
      },
      {
        "condition": "NOT reset AND enqueue rising edge AND count < capacity",
        "action": "Copy the sampled item to buffer[lowerBound + tail], advance tail with wraparound, increment count, and set status to 16#0000."
      },
